from collections import Counter
g=G['Test input']
for bi in range(9):
    for bj in range(9):
        blk=[g[3*bi+i][3*bj:3*bj+3] for i in range(3)]
        c=Counter(x for r in blk for x in r if x!=5)
        vals=c.most_common()
        if len(vals)>1 and vals[0][1]==vals[1][1]:
            print('tie',bi,bj,vals)
